type Tercile = 1 | 2 | 3;

interface SampleTask {
  id: string;
  tercile: Tercile;
  eligible: boolean;
}

const TERCILES: Tercile[] = [3, 2, 1];

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function shuffle<T>(items: T[], rand: () => number): T[] {
  const out = items.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [out[i], out[j]] = [out[j]!, out[i]!];
  }
  return out;
}

/** Stratified, deterministic pick of up to `max` eligible tasks; output sorted by id. */
export function sampleTasks(
  tasks: SampleTask[],
  opts: { max: number; seed: number },
): string[] {
  const pools = new Map<Tercile, string[]>(TERCILES.map((t) => [t, []]));
  for (const t of tasks) if (t.eligible) pools.get(t.tercile)?.push(t.id);
  for (const ids of pools.values()) ids.sort();

  const total = [...pools.values()].reduce((n, p) => n + p.length, 0);
  let budget = Math.max(0, Math.min(Math.floor(opts.max), total));

  // Even split, remainder to the highest terciles first.
  const base = Math.floor(budget / 3);
  const extra = budget % 3;
  const quota = new Map<Tercile, number>();
  TERCILES.forEach((t, i) => {
    quota.set(t, Math.min(base + (i < extra ? 1 : 0), pools.get(t)!.length));
  });

  // Redistribute a short tercile's leftover, one at a time, highest tercile first.
  let left = budget - [...quota.values()].reduce((n, q) => n + q, 0);
  while (left > 0) {
    for (const t of TERCILES) {
      if (left > 0 && quota.get(t)! < pools.get(t)!.length) {
        quota.set(t, quota.get(t)! + 1);
        left--;
      }
    }
  }

  const rand = mulberry32(opts.seed);
  const picked: string[] = [];
  for (const t of [1, 2, 3] as Tercile[]) {
    picked.push(...shuffle(pools.get(t)!, rand).slice(0, quota.get(t)!));
  }
  return picked.sort();
}
EOF
cat > tests/sample.test.ts <<'EOF'
import { describe, expect, test } from "bun:test";
import { sampleTasks } from "../src/replay/sample";

type T = { id: string; tercile: 1 | 2 | 3; eligible: boolean };
const mk = (tercile: 1 | 2 | 3, n: number, eligible = true): T[] =>
  Array.from({ length: n }, (_, i) => ({ id: `t${tercile}-${String(i).padStart(2, "0")}`, tercile, eligible }));
const count = (ids: string[], t: number) => ids.filter((i) => i.startsWith(`t${t}-`)).length;

describe("sampleTasks", () => {
  const tasks = [...mk(1, 10), ...mk(2, 10), ...mk(3, 10)];

  test("even allocation, sorted output", () => {
    const out = sampleTasks(tasks, { max: 9, seed: 1 });
    expect([count(out, 1), count(out, 2), count(out, 3)]).toEqual([3, 3, 3]);
    expect(out).toEqual([...out].sort());
  });

  test("remainder goes to highest terciles first", () => {
    const a = sampleTasks(tasks, { max: 10, seed: 1 });
    expect([count(a, 1), count(a, 2), count(a, 3)]).toEqual([3, 3, 4]);
    const b = sampleTasks(tasks, { max: 11, seed: 1 });
    expect([count(b, 1), count(b, 2), count(b, 3)]).toEqual([3, 4, 4]);
  });

  test("only eligible tasks", () => {
    const out = sampleTasks([...mk(1, 5, false), ...mk(2, 5), ...mk(3, 5)], { max: 12, seed: 1 });
    expect(count(out, 1)).toBe(0);
    expect(out.length).toBe(10);
  });

  test("short tercile leftover filled from others", () => {
    const out = sampleTasks([...mk(1, 1), ...mk(2, 10), ...mk(3, 10)], { max: 12, seed: 1 });
    expect(out.length).toBe(12);
    expect(count(out, 1)).toBe(1);
    expect([count(out, 2), count(out, 3)]).toEqual([5, 6]);
  });

  test("deterministic, input-order independent, seed-sensitive", () => {
    const a = sampleTasks(tasks, { max: 6, seed: 42 });
    expect(sampleTasks([...tasks].reverse(), { max: 6, seed: 42 })).toEqual(a);
    expect(sampleTasks(tasks, { max: 6, seed: 43 })).not.toEqual(a);
  });

  test("edge cases", () => {
    expect(sampleTasks([], { max: 5, seed: 1 })).toEqual([]);
    expect(sampleTasks(tasks, { max: 0, seed: 1 })).toEqual([]);
    expect(sampleTasks(mk(1, 2), { max: 12, seed: 1 }).length).toBe(2);
  });
});
EOF
